    "C45", "C49", "C50", "C55", "C62", "C61", "C60", "C56", "C64", "C63"
  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C01", "C17", "C18", "C07", "C11", "C04", "C02", "C10", "C03", "C06",
    "C45", "C49", "C50", "C55", "C62", "C61", "C60"
  ],
  "claims": [
    {
      "claim": "Reference contexts sharing the query's basic amine and heteroaryl aniline features report absolute oral bioavailability values well above 20%: delpazolid ~99.75%, brigatinib 46%, GSK1322322 46-77%, rufloxacin at least 50%, S-RCP solution 65%, tolvaptan 56%, prasugrel ~79%, amsacrine 32%, and sildenafil 41%.",
      "card_ids": ["C01", "C17", "C18", "C07", "C11", "C04", "C02", "C10", "C03", "C06"]
    },
    {
      "claim": "L4 Caco-2 and human Peff records for structurally related kinase inhibitors (gefitinib, vandetanib) show high permeability despite ionizable basic amine and BCS class II solubility, supporting that the query's absorption component is not an affirmative F<20% liability.",
      "card_ids": ["C45", "C49", "C50", "C55"]
    },
    {
      "claim": "L5 bidirectional Caco-2 records for analogs bearing the same 3-chloro-4-fluorophenyl and basic amine motifs show high A-B permeability (28.6-30.2 x 10^-6 cm/s) and low efflux ratios (0.45-0.68), indicating no affirmative gut-wall efflux liability for this chemotype.",
      "card_ids": ["C62", "C61", "C60", "C56", "C64", "C63"]
    },
    {
      "claim": "Gefitinib efflux substrate records (C57, C66) concern a different molecule and do not establish F<20% for the query; efflux substrate status alone is not threshold-relevant oral-bioavailability evidence.",
      "card_ids": ["C57", "C66"]
    },
    {
      "claim": "No L1-L5 record affirmatively supports F<20% for the query; the lowest human absolute value among reference contexts is amsacrine at 32%, and the remaining L4/L5 records concern other molecules or formulations.",
      "card_ids": ["C03", "C45", "C49", "C50", "C55", "C62", "C61"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C62", "C61", "C60", "C56", "C64", "C63"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in this record set.",
    "No query-specific oral-versus-IV AUC comparison, dose, formulation, or fed/fasted data are available.",
    "L5 efflux/permeability records are for close analogs rather than the query; no query-specific Caco-2, efflux ratio, or intestinal metabolism measurement is provided.",
    "Gefitinib efflux substrate records (C57, C66) are for a different molecule and do not transfer as affirmative low-F evidence.",
    "The physicochemical prior is mixed; high ionization (neutral fraction 0.04) could affect absorption but is not affirmative evidence of F<20%.",
    "Transfer from reference contexts is qualitative; none is an exact structural match to the query."
  ],
  "decision_summary": "L5 adds bidirectional Caco-2 records showing high permeability and low efflux ratios for analogs with the same 3-chloro-4-fluorophenyl and basic amine features, directly addressing the gut-wall efflux concern. No L5 record affirmatively indicates F<20%; gefitinib efflux substrate records concern a different molecule and are not threshold-relevant. Reference contexts with similar features report absolute oral bioavailability values of 32-99.75%, all above 20%. Therefore F>=20% remains better supported; prediction high with moderate confidence."
}

